import { z } from "zod";

/**
 * IDs are UUID strings generated by the client (UUIDv7 recommended so they sort by time).
 * Client-generated IDs let the Flutter app create records offline and keep the same ID after sync.
 */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
export const Id = z.string().toLowerCase().regex(UUID_RE, "Must be a UUID");

/**
 * A farm-local calendar date (no time, no zone), e.g. "2026-10-06".
 * Business dates (record date, sale date, due date) are always LocalDate and are
 * interpreted in the farm's timezone. Instants (createdAt) are ISO-8601 UTC strings.
 */
const LOCAL_DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
export function isValidLocalDate(value: string): boolean {
  const m = LOCAL_DATE_RE.exec(value);
  if (!m) return false;
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
}
export const LocalDate = z.string().refine(isValidLocalDate, "Must be a valid date in YYYY-MM-DD format");

export const Instant = z.string().datetime({ offset: true });

export function isValidTimezone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}
export const IanaTimezone = z.string().min(1).refine(isValidTimezone, "Must be an IANA timezone such as Asia/Kolkata");

const SUPPORTED_CURRENCIES = new Set(
  typeof Intl.supportedValuesOf === "function" ? Intl.supportedValuesOf("currency") : [],
);
export function isValidCurrency(code: string): boolean {
  return /^[A-Z]{3}$/.test(code) && (SUPPORTED_CURRENCIES.size === 0 || SUPPORTED_CURRENCIES.has(code));
}
export const CurrencyCode = z.string().toUpperCase().refine(isValidCurrency, "Must be an ISO 4217 currency code");

/** ISO 3166-1 alpha-2 country code. */
export const CountryCode = z.string().toUpperCase().regex(/^[A-Z]{2}$/);

/**
 * Money is integer minor units + currency. ₹1,250.50 → { amountMinor: 125050, currency: "INR" }.
 * Never floats. Negative amounts are not used: direction is explicit on ledger entries.
 */
export const Money = z.object({
  amountMinor: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER),
  currency: CurrencyCode,
});

export const Count = z.number().int().nonnegative().max(10_000_000);
export const PositiveCount = z.number().int().positive().max(10_000_000);

/** Canonical stored units. Field names carry the unit: weightG, feedKg, temperatureC. */
export const Grams = z.number().nonnegative().max(50_000);
export const Kilograms = z.number().nonnegative().max(100_000_000);
export const Celsius = z.number().min(-60).max(70);
export const Percent = z.number().min(0).max(100);

export const NonEmptyText = (max = 200) => z.string().trim().min(1).max(max);
export const OptionalText = (max = 2000) => z.string().trim().max(max).optional();

export const Email = z.string().trim().toLowerCase().email().max(254);
export const Password = z
  .string()
  .min(10, "Use at least 10 characters")
  .max(200)
  .refine((v) => /[A-Za-z]/.test(v) && /\d/.test(v), "Use letters and at least one number");

export const GeoPoint = z.object({
  lat: z.number().min(-90).max(90),
  lng: z.number().min(-180).max(180),
});

export const Cursor = z.string().max(500);
export const PageQuery = z.object({
  cursor: Cursor.optional(),
  limit: z.coerce.number().int().min(1).max(200).default(50),
});
